* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
  background: radial-gradient(1200px 600px at 20% -10%, #1b2336 0%, transparent 60%),
              radial-gradient(900px 500px at 100% 110%, #16243a 0%, transparent 55%),
              var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 460px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 28px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
}

.card h1 {
  margin: 0 0 6px;
  font-size: 1.4rem;
  letter-spacing: 0.2px;
}

.card .lede {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 0.95rem;
}

.form-field {
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px;
  margin-bottom: 18px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.form-field:focus-within {
  border-color: var(--border-focus);
  box-shadow: var(--focus-ring);
}

.form-field.has-error {
  border-color: var(--error);
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.checkbox-row input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  margin: 2px 0 0;
  flex: 0 0 auto;
  border: 1px solid #4a5468;
  border-radius: 5px;
  background: #0f1422;
  display: inline-grid;
  place-content: center;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.checkbox-row input[type="checkbox"]:hover {
  border-color: var(--accent);
}

.checkbox-row input[type="checkbox"]:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-color: var(--accent);
}

.checkbox-row input[type="checkbox"]::before {
  content: "";
  width: 12px;
  height: 12px;
  transform: scale(0);
  transition: transform 0.12s ease-in-out;
  background: var(--accent);
  clip-path: polygon(14% 44%, 0 60%, 40% 100%, 100% 18%, 86% 4%, 39% 70%);
}

.checkbox-row input[type="checkbox"]:checked {
  background: #0f1422;
  border-color: var(--accent);
}

.checkbox-row input[type="checkbox"]:checked::before {
  transform: scale(1);
}

.checkbox-label {
  display: block;
  font-weight: 500;
  cursor: pointer;
  color: var(--text);
}

.checkbox-label .req {
  color: var(--error);
  margin-left: 2px;
}

.helper-text {
  display: block;
  margin-top: 6px;
  font-size: 0.85rem;
  color: var(--muted);
}

.error-text {
  display: block;
  margin-top: 8px;
  font-size: 0.85rem;
  color: var(--error);
}

a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}
a:hover { color: var(--accent-hover); }
a:focus-visible {
  outline: none;
  border-radius: 3px;
  box-shadow: var(--focus-ring);
}

.submit-btn {
  width: 100%;
  padding: 12px 16px;
  border-radius: 10px;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: var(--accent-contrast);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease;
}
.submit-btn:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
.submit-btn:active { transform: translateY(1px); }
.submit-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.status {
  margin-top: 14px;
  font-size: 0.9rem;
  color: var(--success);
  min-height: 1.25em;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}
